if __name__ == "__main__":
    import argparse
    from collections import Counter

    parser = argparse.ArgumentParser()
    parser.add_argument("--dump_jiras", help="Dump jira IDs from the input directory")
    parser.add_argument("-df", "--dump_tests_from_jira", help="Dump all the tests in a jira, accross all files")
    parser.add_argument("-asic", "--asic_id", default="gaudi", help="Asci id")
    parser.add_argument("--dump_top_jiras", help="Dump TCs in file impacting the top Jiras from input directory ")
    parser.add_argument("--dump_tests_for_runjira", help="Dump TCs for runjira job")
    args = parser.parse_args()

    if args.dump_jiras:
        for key, val in file_wise_xfails_dict[args.dump_jiras].items():
            if key.startswith("https://jira.habana-labs.com/browse/") and val != "":
                tc_list = val.split(";")
                print(key, ":", len(tc_list))
    elif args.dump_tests_from_jira:
        tests_list = []
        for file, jiras in file_wise_xfails_dict.items():
            for jira, tests in jiras.items():
                if args.dump_tests_from_jira in jira:
                    tests_list.extend(tests.split(";"))
        import pprint

        pprint.pprint(tests_list)
    elif args.dump_top_jiras:
        counter = Counter(all_xfails_dict.values()) + Counter(all_hangs_dict.values())
        jira_list = []
        for value, count in counter.most_common(5):
            jira_list.append(value)
        for top_jira in jira_list:
            for file, jiras in file_wise_xfails_dict.items():
                if file == args.dump_top_jiras:
                    for jira, tests in jiras.items():
                        if top_jira in jira:
                            print("{}@{}".format(jira.removeprefix("https://jira.habana-labs.com/browse/"), tests))
    elif args.dump_tests_for_runjira:
        counter = Counter(all_xfails_dict.values()) + Counter(all_hangs_dict.values())
        jira_list = []
        test_list = []
        for value, count in counter.items():
            jira_list.append(value)
        for top_jira in jira_list:
            for file, jiras in file_wise_xfails_dict.items():
                if file == args.dump_tests_for_runjira:
                    for jira, tests in jiras.items():
                        if top_jira in jira:
                            line = "{}@{}".format(jira.removeprefix("https://jira.habana-labs.com/browse/"), tests)
                            if line not in test_list:
                                test_list.append(line)
        for test in test_list:
            print(test)

    else:
        counter = Counter(all_xfails_dict.values()) + Counter(all_hangs_dict.values())
        print("20 issues impacting biggest number of tests are:")
        for value, count in counter.most_common(20):
            print(value, count)
